import{_ as e,o,c as i,a2 as r}from"./chunks/framework.OLpNgP4A.js";const g=JSON.parse('{"title":"GitHub Student Developer Pack Guide","description":"A complete guide on how to apply for and verify the GitHub Student Developer Pack.","frontmatter":{"title":"GitHub Student Developer Pack Guide","description":"A complete guide on how to apply for and verify the GitHub Student Developer Pack."},"headers":[],"relativePath":"github-student-pack.md","filePath":"github-student-pack.md","lastUpdated":1789221836000}'),a={name:"github-student-pack.md"};function n(s,t,l,u,d,c){return o(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="github-student-developer-pack-guide" tabindex="-1">GitHub Student Developer Pack Guide <a class="header-anchor" href="#github-student-developer-pack-guide" aria-label="Permalink to &quot;GitHub Student Developer Pack Guide&quot;">​</a></h1><p><strong>Yes!</strong> Here&#39;s a <strong>complete, up-to-date (2026) detailed guide</strong> on how to apply for and verify the <strong>GitHub Student Developer Pack</strong> (also called GitHub Education / Global Campus for Students). This gives you free GitHub Pro, Copilot Student, Codespaces, and dozens of partner offers (Azure credits, DigitalOcean, etc.).</p><h3 id="_1-eligibility-requirements-must-meet-all" tabindex="-1">1. Eligibility Requirements (Must Meet ALL) <a class="header-anchor" href="#_1-eligibility-requirements-must-meet-all" aria-label="Permalink to &quot;1. Eligibility Requirements (Must Meet ALL)&quot;">​</a></h3><p>You qualify if you:</p><ul><li>Are <strong>at least 13 years old</strong>.</li><li>Are <strong>currently enrolled</strong> in a <strong>degree- or diploma-granting program</strong> (high school, college, university, or homeschool). Bootcamps/coding schools usually <strong>do not</strong> qualify unless your school joins the GitHub Campus Program.</li><li>Have a <strong>verifiable school-issued email</strong> OR official documents proving current enrollment.</li><li>Own a <strong>personal GitHub account</strong> (not an organization account).</li></ul><p><strong>Important</strong>: Verification is <strong>free</strong> and lasts ~2 years (you may need to re-verify later).</p><h3 id="_2-prerequisites-do-these-first" tabindex="-1">2. Prerequisites (Do These First) <a class="header-anchor" href="#_2-prerequisites-do-these-first" aria-label="Permalink to &quot;2. Prerequisites (Do These First)&quot;">​</a></h3><ol><li>Create a <strong>personal GitHub account</strong> at <a href="https://github.com/join" target="_blank" rel="noreferrer">github.com/join</a> (if you don’t have one).</li><li><strong>Add and verify</strong> your school email (if you have one) in GitHub Settings → Emails.</li><li><strong>Enable 2-Factor Authentication (2FA)</strong> — strongly recommended.</li><li><strong>Update your GitHub profile</strong>: <ul><li>Full legal name <strong>exactly</strong> as it appears on your school documents (no nicknames).</li><li>Add a short bio.</li></ul></li><li><strong>Add billing information</strong> (Settings → Billing and plans) — even if you’re not paying anything.</li></ol><p><strong>Pro tip</strong>: Log out and log back into GitHub before starting the application.</p><h3 id="_3-step-by-step-application-process" tabindex="-1">3. Step-by-Step Application Process <a class="header-anchor" href="#_3-step-by-step-application-process" aria-label="Permalink to &quot;3. Step-by-Step Application Process&quot;">​</a></h3><p>The verification process is now integrated into your GitHub account settings (updated in 2025–2026).</p><ol><li><p>Go to <strong>GitHub Settings</strong> → Click your profile picture (top right) → <strong>Settings</strong>.</p></li><li><p>In the left sidebar, click <strong>Billing and plans</strong> → <strong>Plans and usage</strong>.</p></li><li><p>Scroll to the <strong>“GitHub Education”</strong> section.</p></li><li><p>Click <strong>“Start an application”</strong> or <strong>“Get Student Developer Pack”</strong>.</p><ul><li>Alternative direct link (if it works): <a href="https://github.com/settings/billing/summary#education-benefits" target="_blank" rel="noreferrer">https://github.com/settings/billing/summary#education-benefits</a> or <a href="https://education.github.com/benefits" target="_blank" rel="noreferrer">education.github.com/benefits</a>.</li></ul></li><li><p>Fill out the form:</p><ul><li>Select <strong>Student</strong> as your role.</li><li>Enter your <strong>school name</strong> (search for it or add manually).</li><li>Provide your <strong>school email</strong> if available (highly recommended — speeds up approval).</li><li>If no school email or untrusted domain → You’ll be prompted to <strong>upload proof</strong>.</li></ul></li><li><p>Upload proof (if required):</p><ul><li>Accepted documents (one or more): <ul><li>Picture of your <strong>school ID card</strong> (must show current enrollment/validity date).</li><li><strong>Class schedule</strong>.</li><li><strong>Transcript</strong>.</li><li><strong>Enrollment verification / affiliation letter</strong> on school letterhead.</li></ul></li><li>Requirements for documents: <ul><li>Clear, well-lit, <strong>unedited</strong> photo (take a fresh photo with your phone camera).</li><li>Must clearly show: <strong>your full name</strong>, <strong>school name</strong>, and <strong>a current date</strong> (academic year, issue date, or validity date).</li><li>You can combine multiple documents into one image.</li><li>Non-English documents? Add a clear English translation beside the original.</li></ul></li></ul></li><li><p>Click <strong>Submit application</strong>.</p></li></ol><h3 id="_4-after-submission-–-what-to-expect" tabindex="-1">4. After Submission – What to Expect <a class="header-anchor" href="#_4-after-submission-–-what-to-expect" aria-label="Permalink to &quot;4. After Submission – What to Expect&quot;">​</a></h3><ul><li><strong>Processing time</strong>: Usually <strong>a few days</strong>, but can take <strong>up to 6 weeks</strong> during peak periods (start of semesters).</li><li>You’ll get an email when it’s approved (or rejected).</li><li>Once approved: <ul><li>Go to your <strong><a href="https://github.com/education" target="_blank" rel="noreferrer">GitHub Education portal</a></strong> or <a href="https://education.github.com" target="_blank" rel="noreferrer">education.github.com</a>.</li><li>Claim individual offers (GitHub Pro, Copilot Student, etc.).</li></ul></li><li>Benefits appear within 3–5 days.</li></ul><h3 id="_5-common-rejection-reasons-how-to-fix-them-most-important-section" tabindex="-1">5. Common Rejection Reasons &amp; How to Fix Them (Most Important Section) <a class="header-anchor" href="#_5-common-rejection-reasons-how-to-fix-them-most-important-section" aria-label="Permalink to &quot;5. Common Rejection Reasons &amp; How to Fix Them (Most Important Section)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rejection Reason</th><th>Why It Happens</th><th>How to Fix (Re-apply)</th></tr></thead><tbody><tr><td>Blurry / unclear document</td><td>Photo is low quality or cropped</td><td>Take a new, well-lit photo. No edits.</td></tr><tr><td>No current date shown</td><td>Document is expired or undated</td><td>Use a document with visible current academic year/date</td></tr><tr><td>Name mismatch</td><td>GitHub profile name ≠ document name</td><td>Update GitHub profile to exact legal name</td></tr><tr><td>Wrong school email domain</td><td>School not recognized or lax policy</td><td>Upload extra document + contact school IT if needed</td></tr><tr><td>Already used email on another account</td><td>Multiple accounts</td><td>Merge accounts (allowed under GitHub ToS)</td></tr><tr><td>Location / VPN issue</td><td>Detected as not near campus</td><td>Disable VPN, allow browser location access, try from campus or different network</td></tr><tr><td>School doesn’t issue emails</td><td>Common in some countries</td><td>Use official documents only (letterhead + date)</td></tr><tr><td>Previous proof flagged</td><td>Bad actors used same document</td><td>Take a <strong>new live photo</strong> of your document</td></tr></tbody></table><p><strong>Re-apply tip</strong>: GitHub <strong>combines</strong> all your previous submissions. Add <strong>new supplementary proof</strong> each time.</p><h3 id="_6-dos-and-don-ts-critical-for-success" tabindex="-1">6. Dos and Don’ts (Critical for Success) <a class="header-anchor" href="#_6-dos-and-don-ts-critical-for-success" aria-label="Permalink to &quot;6. Dos and Don’ts (Critical for Success)&quot;">​</a></h3><p><strong>Do</strong> ✅:</p><ul><li>Use your <strong>real full legal name</strong> everywhere.</li><li>Prepare documents <strong>before</strong> starting (have them ready on your device).</li><li>Take fresh photos — never upload old/screenshot/cropped ones.</li><li>Disable VPN and allow location/camera permissions.</li><li>Use Chrome (best compatibility).</li><li>Re-apply immediately after fixing issues.</li><li>If stuck, post in <a href="https://github.com/orgs/community/discussions/categories/github-education" target="_blank" rel="noreferrer">GitHub Education Community Discussions</a> or open a support ticket at <a href="https://support.github.com/contact/education" target="_blank" rel="noreferrer">support.github.com/contact/education</a>.</li></ul><p><strong>Don’t</strong> ❌:</p><ul><li>Edit, crop, or Photoshop documents (instant flag).</li><li>Use nicknames or mismatched names.</li><li>Apply with expired/old documents.</li><li>Expect instant approval — be patient.</li><li>Use the same email on multiple GitHub accounts.</li><li>Apply if you’re not <strong>currently enrolled</strong>.</li><li>Open support tickets just to “speed up” — they can’t expedite.</li></ul><h3 id="_7-bonus-tips-especially-for-malaysia-international-students" tabindex="-1">7. Bonus Tips (Especially for Malaysia / International Students) <a class="header-anchor" href="#_7-bonus-tips-especially-for-malaysia-international-students" aria-label="Permalink to &quot;7. Bonus Tips (Especially for Malaysia / International Students)&quot;">​</a></h3><ul><li>Many Malaysian universities provide <code>@student.university.edu.my</code> emails → use them!</li><li>If your school doesn’t issue emails → an <strong>official enrollment letter</strong> or <strong>student ID with validity date</strong> works very well.</li><li>Take photos in good lighting. If your document is in Malay/Chinese, add an English translation.</li><li>High school students are fully eligible.</li></ul><h3 id="_8-once-approved-–-what-you-get" tabindex="-1">8. Once Approved – What You Get <a class="header-anchor" href="#_8-once-approved-–-what-you-get" aria-label="Permalink to &quot;8. Once Approved – What You Get&quot;">​</a></h3><ul><li>GitHub Pro</li><li>Copilot Student (enhanced free tier)</li><li>Free Codespaces, GitHub Pages, etc.</li><li>Partner credits (Azure, AWS Educate, DigitalOcean, etc.)</li><li>Learning resources and certifications</li></ul><p>You can now go claim everything at the Education portal.</p><p><strong>Need help?</strong> Drop a screenshot of your rejection email (redact personal info) and I can tell you exactly what to fix.</p><p>Good luck — most students get approved on the first or second try when they follow these steps! 🚀</p><p>Let me know if you want me to walk you through any specific step live.</p>',30)])])}const h=e(a,[["render",n]]);export{g as __pageData,h as default};
